import{_ as a,H as t,f as i,i as p}from"./chunks/framework.BH2BK_3i.js";const I=JSON.parse('{"title":"开篇词 | 开发工程师如何进阶为AI应用型人才？","description":"","frontmatter":{},"headers":[{"level":2,"title":"转型为 AI 应用型工程师的难点","slug":"转型为-ai-应用型工程师的难点","link":"#转型为-ai-应用型工程师的难点","children":[]},{"level":2,"title":"开发工程师入局 AI 的最佳路径","slug":"开发工程师入局-ai-的最佳路径","link":"#开发工程师入局-ai-的最佳路径","children":[]},{"level":2,"title":"这门课程是如何设计的？","slug":"这门课程是如何设计的","link":"#这门课程是如何设计的","children":[]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]}],"relativePath":"AI大模型实战高手课/开篇词｜开发工程师如何进阶为AI应用型人才？.md","filePath":"AI大模型实战高手课/开篇词｜开发工程师如何进阶为AI应用型人才？.md","lastUpdated":1795452664000}'),A={name:"AI大模型实战高手课/开篇词｜开发工程师如何进阶为AI应用型人才？.md"};function l(n,e,r,s,E,o){return t(),i("div",null,[...e[0]||(e[0]=[p('<h1 id="开篇词-开发工程师如何进阶为ai应用型人才" tabindex="-1">开篇词 | 开发工程师如何进阶为AI应用型人才？ <a class="header-anchor" href="#开篇词-开发工程师如何进阶为ai应用型人才" aria-label="Permalink to &quot;开篇词 | 开发工程师如何进阶为AI应用型人才？&quot;">​</a></h1><p>你好，我是独行。欢迎你加入这个专栏，和我来一场 AI 大模型深度游。</p><p>我先来简单介绍一下自己，我在互联网行业已经十年多了，目前在一家科技公司任 CTO，面向企业级客户提供平台化相关产品，现在主要的研究方向是分布式系统架构、人工智能、物联网、低代码。</p><p>我之前也曾在阿里巴巴、IBM 等公司任职，毕业五年时间晋升到高级技术专家（P8）。职业生涯中 80% 的经历都是 ToB 相关的。也曾有作为技术合伙人参与过从 0 到 1 创业，做到细分市场 TOP 级的经历。虽然期间换过几次行业，但是技术研究方向基本没变。</p><p>近年来，我开始深入研究 AI 领域，阅读了数百篇相关论文，逐渐领略到这一领域的魅力与潜力。对于我们这些具备开发基础的技术人员来说，AI 无疑是一个充满机遇的新领域。近期的两会上，人工智能也再次成为国家战略焦点，预示着未来十年到十五年的行业发展红利。从互联网 + 到人工智能 +，我们将迎来新一轮技术革新和人才需求的增长。</p><p>我相信，在未来的发展中，AI 将引领我们走向更加智能、高效的新时代，所以它非常值得我们花时间好好去钻研。</p><h2 id="转型为-ai-应用型工程师的难点" tabindex="-1">转型为 AI 应用型工程师的难点 <a class="header-anchor" href="#转型为-ai-应用型工程师的难点" aria-label="Permalink to &quot;转型为 AI 应用型工程师的难点&quot;">​</a></h2><p>对于广大软件开发人员来说，人工智能的深度研究可能会因为它本身的复杂性而令人生畏。然而，我们完全可以将注意力转向人工智能的应用领域。</p><p>其实不用我多说，作为一个技术开发人员，你可能早已投身于这股滚滚热潮之中了，因为人工智能本身就是技术领域的一个重要分支。敏锐如你我，经过这一年多的时间，应该已经尝试了个遍。不过在应用 AI 大模型的过程中，你应该也遇到了很多问题。</p><p>比如：</p><ul><li><p>小团队如何解决 GPU 与存储空间等资源问题？</p></li><li><p>如何在众多模型中选择适合自己领域的模型并进行优化？</p></li><li><p>如何从 0 到 1 构建一个自己领域内的大模型？</p></li><li><p>将微调后的大模型应用于具体的业务场景，要考虑哪些因素？</p></li><li><p>没有机器学习和深度学习基础，怎么深度使用大模型？</p></li><li><p>如何在确保兼容性的情况下，将大模型集成到现有技术栈中？</p></li><li><p>如何让更好地维护并更新大模型？</p></li><li><p>……</p></li></ul><p>无论你是自己探索，还是为企业布局 AI 做准备，这些都是避不开的问题。不过你也不用担心，这些问题你都可以在课程中找到答案。</p><h2 id="开发工程师入局-ai-的最佳路径" tabindex="-1">开发工程师入局 AI 的最佳路径 <a class="header-anchor" href="#开发工程师入局-ai-的最佳路径" aria-label="Permalink to &quot;开发工程师入局 AI 的最佳路径&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>刚刚的那些问题其实也正是开发工程师想要转变为 AI 应用型 工程师的难点。要想克服这些难点，我们首先要做的就是持续更新自己的知识体系，对 AI 的发展和应用情况有一个清楚的认知，来适应 AI 领域的快速变化。现在了解 AI 讯息的渠道很多，无论是公众号、社区，还是一些技术网站，都是稳定的信息来源，可以源源不断地获取最新动态。</p><p>其次是部署一些有代表性的模型产品进行试用，比如 LLaMA、ChatGLM 等，为你后面大模型选型打下基础，毕竟体验过后才有发言权。</p><p>此外你还需要学习相关的技术，AI 技术的本质是机器学习，是一个独立的技术体系，学习起来会有一定的难度，不过这些机器学习的原理并不要求你全部掌握，只掌握你领域内最核心的技术原理就可以了，比如大语言模型技术原理中的 Transformer 架构、Word2Vec 等等。</p><p>最后，积累丰富的实际项目经验同样至关重要，这有助于将理论知识有效地转化为解决具体业务问题的能力，这也正是企业最看重的一项能力。生成式 AI 适合大部分行业，因为符合人类语言环境，只要有语言的地方，基本都能找到生成式 AI 的适用场景，即便你所在行业业务方面没有适用的场景，但是我们还是可以把 AI 作为个人助手，来辅助我们做很多事情，所以你要想办法找到场景，将自己所学的技术进行实践。</p><p>对于想要入局 AI 的研发工程师，我觉得最好的学习路径就是这样。</p><h2 id="这门课程是如何设计的" tabindex="-1">这门课程是如何设计的？ <a class="header-anchor" href="#这门课程是如何设计的" aria-label="Permalink to &quot;这门课程是如何设计的？&quot;">​</a></h2><p>我根据这条最佳的学习路径，由浅入深地把课程分成了 5 个章节。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" alt=""></a></p><p>第一章：小试牛刀，理解基础概念</p><p>在这部分，我会向你介绍 ChatGPT 的发展，以及大语言模型中非常重要的概念：提示和智能体。学完了这一章的内容之后，你就会初步认识到 AI 的重要性，对研发工程师该着重从哪方面入手有一个清晰的认知。</p><p>第二章：超燃实战，深度玩转 AI 模型</p><p>这一章，我会带你进行各种尝试，来感受大模型的魅力，学完这一章，你将学会如何部署、微调、RAG、封装大模型，这部分内容就是你在企业里落地大模型应用的基础。</p><p>第三章：打入核心，挑战底层技术原理</p><p>从这一章开始，我会带你深入技术细节，理解大模型的原理。相信你在体验完大模型后，一定会有很多疑问，比如大模型的权重文件里到底存放的是什么？大模型推理原理是什么样的？所有的疑问将会在学完这一章后全部解开。</p><p>第四章：终极玩法，从 0 到 1 构建大模型当你学完原理后如何才能将所学知识吃透呢？那就需要亲自上手实战了，我们将使用上一章学到的知识，自己一步一步构建一个大模型，你甚至可以根据自己的需求去构建其他模型，比如翻译、分类、个人小助手等场景，我相信这会非常酷。</p><p>第五章：热点速递，AI 行业发展趋势预测</p><p>这一章节我们会深入探讨了 AI 行业的最新发展趋势，包括 Mamba 模型、Sora、机器人与大模型、人工智能与无人机，以及 AI 发展的下一阶段 Q-Star(*) 的概念。通过学习这些内容，你将了解到 AI 技术如何在不同领域产生深远影响，以及这些新兴技术将会如何塑造我们未来的工作和生活方式。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>无论你当前处于何种阶段，是否已具备 AI 技术基础，都不必过于忧虑。根据创新扩散定律，当前 AI 领域正处于早期接受者的阶段，这意味着行业仍在快速发展但尚未成熟的阶段。因此，你拥有足够的时间来深入学习和探索。我们要保持短期跟进，长期看好的心态。人工智能无疑是未来的趋势，大方向不会错。现在就是上车的好时机，跟上队伍的节奏，不断学习和进步。</p><p>我希望在探索人工智能的道路上你不仅仅能够学到 AI 相关的知识，更重要的能够养成数据驱动与模型驱动的思维，掌握处理和分析数据的技能，将数据作为大模型的基石，深刻理解模型的工作原理和应用场景。希望这门课程能够为你打开人工智能技术世界的大门，激发你的灵感，引领你走向更广阔的未来。</p><p>戳此加入课程交流群</p>',35)])])}const _=a(A,[["render",l]]);export{I as __pageData,_ as default};
